]

const hariIni = new Date()
const bulan = ref(hariIni.getMonth() + 1)
const tahun = ref(hariIni.getFullYear())

const rows = ref([])
const ringkasan = ref({ menunggu: 0, diputuskan: 0, total: 0, sisa_hari: null, cabang: [] })
const start = ref(0)
const hasMore = ref(false)
const loading = ref(false)
const sibuk = ref(false)
const error = ref('')

const cabang = ref('')
const cari = ref('')
const tampilSemua = ref(false)
const modePilih = ref(false)
const terpilih = ref(new Set())
const detail = ref(null)
const tolakUntuk = ref(null)
const alasanTolak = ref('')
const galatTolak = ref('')

const labelPeriode = computed(() => `Periode ${BULAN[bulan.value - 1]} ${tahun.value}`)

// Periode setelah bulan berjalan belum punya data; majunya dikunci supaya tidak
// terlihat seperti datanya hilang.
const bolehMaju = computed(
	() =>
		tahun.value < hariIni.getFullYear() ||
		(tahun.value === hariIni.getFullYear() && bulan.value < hariIni.getMonth() + 1)
)

const lewatBatas = computed(() => (ringkasan.value.sisa_hari ?? 1) < 0)
const mendesak = computed(() => {
	const n = ringkasan.value.sisa_hari
	return n !== null && n !== undefined && n <= 3
})
// Angka negatif ditampilkan sebagai jumlah hari keterlambatan, dengan labelnya
// yang berubah — bukan dipangkas ke nol, karena itu menyembunyikan masalahnya.
const sisaTeks = computed(() => {
	const n = ringkasan.value.sisa_hari
	if (n === null || n === undefined) return '—'
	return String(Math.abs(n))
})

function inisial(nama) {
	return String(nama || '?')
		.split(/\s+/)
		.slice(0, 2)
		.map((w) => w[0] || '')
		.join('')
		.toUpperCase()
}

function warnaMenit(row) {
	const m = Number(row.menit_terlambat) || 0
	if (m >= 30) return 'text-ui-ink-red-600'
	if (m >= 10) return 'text-ui-ink-amber-600'
	return 'text-ui-ink-gray-600'
}

function teksRiwayat(row) {
	const r = row.riwayat_periode
	if (!r || !r.total) return 'Periode ini: keterlambatan pertama'
	return `Periode ini: ${r.total} kali terlambat, ${r.dimaafkan} dimaafkan`
}

const list = createResource({
	url: 'juragan.api.portal.keterlambatan.get_antrean_ketua',
	auto: false,
	makeParams() {
		return {
			bulan: bulan.value,
			tahun: tahun.value,
			cabang: cabang.value || undefined,
			q: cari.value || undefined,
			status: tampilSemua.value ? 'semua' : undefined,
			limit: PER_HALAMAN,
			start: start.value,
		}
	},
	onSuccess(data) {
		const batch = data || []
		rows.value = start.value === 0 ? batch : rows.value.concat(batch)
		hasMore.value = batch.length === PER_HALAMAN
		loading.value = false
	},
	onError(err) {
		error.value = err?.messages?.[0] || err?.message || String(err)
		loading.value = false
	},
})

const ringkas = createResource({
	url: 'juragan.api.portal.keterlambatan.get_ringkasan_ketua',
	auto: false,
	makeParams() {
		return { bulan: bulan.value, tahun: tahun.value }
	},
	onSuccess(data) {
		if (data) ringkasan.value = data
	},
	// Handler wajib ada meski kosong: resource tanpa onError melepas unhandled
	// rejection, dan handler global memunculkan toast KEDUA untuk error yang sama.
	onError() {},
})

const detailRes = createResource({
	url: 'juragan.api.portal.keterlambatan.get_detail',
	auto: false,
	onError(err) {
		notifyError(err, 'Gagal membuka detail')
	},
})

const putuskanRes = createResource({
	url: 'juragan.api.portal.keterlambatan.putuskan_massal',
	auto: false,
	onError() {},
})

function reload() {
	error.value = ''
	start.value = 0
	loading.value = true
	terpilih.value = new Set()
	list.fetch()
	ringkas.fetch()
}

function muatLagi() {
	start.value += PER_HALAMAN
	loading.value = true
	list.fetch()
}

function geserPeriode(arah) {
	let b = bulan.value + arah
	let t = tahun.value
	if (b < 1) {
		b = 12
		t -= 1
	} else if (b > 12) {
		b = 1
		t += 1
	}
	bulan.value = b
	tahun.value = t
	reload()
}

function pilihCabang(c) {
	cabang.value = c
	reload()
}

function toggleSemua() {
	tampilSemua.value = !tampilSemua.value
	reload()
}

function togglePilih(name) {
	// Set diganti utuh, bukan dimutasi: Vue tidak melacak perubahan isi Set.
	const s = new Set(terpilih.value)
	if (s.has(name)) s.delete(name)
	else s.add(name)
	terpilih.value = s
}

// Detail dibuka sebagai lembar dari bawah, bukan halaman terpisah: memutuskan
// puluhan keterlambatan berarti bolak-balik, dan tiap perpindahan halaman
// berarti kehilangan posisi gulir serta filter yang sedang dipakai.
// Di mode pilih, menekan kartu berarti memilihnya — itu yang sedang dikerjakan
// user, dan menyodorkan detail justru memotong pekerjaannya.
function tekanKartu(row) {
	if (modePilih.value && row.boleh_diputuskan) {
		togglePilih(row.name)
		return
	}
	bukaDetail(row)
}

async function bukaDetail(row) {
	// Lembar dibuka SEKARANG dari data yang sudah ada di kartu — kartu antrean
	// memuat hampir seluruh isi lembar ini. Menunggu panggilan detail lebih dulu
	// membuat ketukan terasa mati beberapa ratus milidetik, dan animasinya baru
	// mulai setelah jaringan menjawab.
	//
	// Riwayat periode hanya dihitung di antrean, jadi ikut dibawa dari sini.
	detail.value = { ...row }

	const d = await detailRes.fetch({ name: row.name })
	// Balasan bisa datang setelah user menutup lembarnya atau membuka kartu
	// lain; menimpanya akan menampilkan orang yang salah.
	if (!d || detail.value?.name !== row.name) return

	detail.value = { ...detail.value, ...d }
}

async function jalankan(names, action, alasan) {
	if (!names.length || sibuk.value) return
	sibuk.value = true
	try {
		const hasil = await putuskanRes.submit({
			names: JSON.stringify(names),
			action,
			alasan_penolakan: alasan,
		})
		const berhasil = hasil?.berhasil?.length || 0
		const gagal = hasil?.gagal || []
		if (berhasil) {
			notifySuccess(
				`${berhasil} keterlambatan ${action === 'Approve' ? 'dimaafkan' : 'ditolak'}.`
			)
		}
		// Sebagian gagal bukan kegagalan seluruhnya — yang berhasil tetap
		// dilaporkan, dan sisanya disebut apa adanya.
		if (gagal.length) {
			notifyError(
				new Error(gagal[0].pesan || 'Sebagian gagal diproses.'),
				`${gagal.length} gagal diproses`
			)
		}
		detail.value = null
		reload()
	} catch (e) {
		notifyError(e, 'Gagal menyimpan keputusan')
	} finally {
		sibuk.value = false
	}
}

function maafkan(names) {
	jalankan(names, 'Approve')
}

function mintaTolak(names) {
	tolakUntuk.value = names
	alasanTolak.value = ''
	galatTolak.value = ''
}

function batalTolak() {
	tolakUntuk.value = null
	galatTolak.value = ''
}

async function kirimTolak() {
	if (!alasanTolak.value) {
		galatTolak.value = 'Isi alasan penolakan dulu.'
		return
	}
	const names = tolakUntuk.value
	tolakUntuk.value = null
	await jalankan(names, 'Reject', alasanTolak.value)
}

onMounted(async () => {
	await refreshCsrfToken()
	reload()
})
</script>
